import { Pool } from 'pg';
import { embeddingService } from '../services/embeddingService.js';
import config from '../config.js';
import Logger from '../utils/logger.js';
import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';

// Setup Env
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
dotenv.config({ path: path.resolve(__dirname, '../../.env') });

async function backfillEmbeddings() {
    Logger.info("🚀 Starting Embedding Backfill Process...");

    // 1. Setup DB Connection
    const pool = new Pool(config.database);
    
    try {
        // 2. Count Targets (Recent News - last 7 days)
        // Optimized to prioritize recent news first
        const daysToLookBack = 7; 
        const countQuery = `
            SELECT COUNT(*) 
            FROM enhanced_news 
            WHERE embedding IS NULL 
            AND timestamp_unix_ms > (EXTRACT(EPOCH FROM NOW()) * 1000 - ${daysToLookBack * 24 * 60 * 60 * 1000})
        `;
        const resCount = await pool.query(countQuery);
        const totalToProcess = parseInt(resCount.rows[0].count);

        Logger.info(`🎯 Found ${totalToProcess} recent articles (last ${daysToLookBack} days) needing embeddings.`);

        if (totalToProcess === 0) {
            Logger.info("✅ No articles to process.");
            return;
        }

        // 3. AUTO-DETECT & MIGRATE DIMENSIONS
        // Generate one probe vector to check dimensions
        Logger.info("🕵️ Probing API for vector dimensions...");
        const probeVector = await embeddingService.generateEmbedding("Probe", { model: 'qwen/qwen3-embedding-8b' });
        const apiDims = probeVector.length;
        Logger.info(`📏 API Model 'qwen/qwen3-embedding-8b' returns ${apiDims} dimensions.`);

        // Check DB Column Type
        const schemaRes = await pool.query(`
            SELECT atttypmod 
            FROM pg_attribute 
            WHERE attrelid = 'enhanced_news'::regclass 
            AND attname = 'embedding'
        `);
        const _dbDims = schemaRes.rows[0]?.atttypmod; // vector typmod is usually dims
        
        // Note: pg_vector typmod needs parsing or just try/catch the insert. 
        // Simpler: Just try to ALTER if catch error implies mismatch? 
        // Better: Always ensure correct type.
        
        // Let's blindly run ALTER if we can, or just log.
        // If apiDims (e.g. 4096) != 1536 (default), execution will fail.
        
        if (apiDims !== 1536) { // Assuming 1536 is the old default
             Logger.warn(`⚠️ Dimension Mismatch! API: ${apiDims} vs DB Default (1536). Initiating Migration...`);
             try {
                 await pool.query(`ALTER TABLE enhanced_news ALTER COLUMN embedding TYPE vector(${apiDims})`);
                 Logger.info(`✅ Schema Updated: embedding column is now vector(${apiDims})`);
             } catch (e: any) {
                 Logger.error(`❌ Migration Failed: ${e.message}. Attempting to proceed anyway...`);
             }
        }

        // 4. Process in Batches
        const BATCH_SIZE = 10;
        let processed = 0;
        let errors = 0;

        // Cursor logic or simple offset
        // Using cursor-like approach by selecting NULLs each time is robust but order matters
        const selectQuery = `
            SELECT id, title, content 
            FROM enhanced_news 
            WHERE embedding IS NULL 
            AND timestamp_unix_ms > (EXTRACT(EPOCH FROM NOW()) * 1000 - ${daysToLookBack * 24 * 60 * 60 * 1000})
            ORDER BY timestamp_unix_ms DESC
            LIMIT ${BATCH_SIZE}
        `;

        while (processed < totalToProcess) {
            const rows = (await pool.query(selectQuery)).rows;
            if (rows.length === 0) break;

            Logger.info(`📦 Processing batch of ${rows.length} articles...`);

            // Parallel Processing within Batch
            await Promise.all(rows.map(async (row) => {
                try {
                    const textToEmbed = `${row.title}\n\n${row.content || ''}`.substring(0, 8000); // Truncate safety
                    
                    // Generate Vector (Qwen via OpenRouter)
                    const vector = await embeddingService.generateEmbedding(textToEmbed, {
                        model: 'qwen/qwen3-embedding-8b',
                        dimensions: 1536 // Or let API decide, but usually standard fixed
                    });

                    // Update DB - Using explicit casting for pgvector
                    // Note: pgvector expects '[...]' string format
                    const vectorStr = `[${vector.join(',')}]`;
                    
                    await pool.query(
                        `UPDATE enhanced_news SET embedding = $1::vector WHERE id = $2`,
                        [vectorStr, row.id]
                    );
                    
                    process.stdout.write('.'); // Progress dot
                } catch (err: any) {
                    process.stdout.write('x');
                    errors++;
                    Logger.error(`Failed ID ${row.id}: ${err.message}`);
                }
            }));
            
            processed += rows.length;
            console.log(`\n📊 Progress: ${processed}/${totalToProcess} (Errors: ${errors})`);
            
            // Rate Limit Safety (optional but good practice)
            await new Promise(r => setTimeout(r, 1000));
        }

        Logger.info("✅ Backfill Complete!");

    } catch (err) {
        Logger.error("❌ Fatal Script Error", err);
    } finally {
        await pool.end();
    }
}

backfillEmbeddings();

#!/usr/bin/env node

import { Pool } from 'pg';
import Logger from '../utils/logger.js';
import { embeddingService } from './embeddingService.js';
import { HybridSearchService } from './hybridSearchService.js';

/**
 * Service de recherche intelligent
 * Détecte automatiquement le mode optimal et route les requêtes
 */
export class IntelligentSearchService {
  private pool: Pool;
  private hybridSearch: HybridSearchService;

  constructor(pool: Pool) {
    this.pool = pool;
    this.hybridSearch = new HybridSearchService(pool);
  }

  /**
   * Point d'entrée principal - Recherche intelligente
   */
  async search(
    query: string,
    options: {
      tableName?: string;
      mode?: 'auto' | 'hybrid' | 'vector' | 'text';
      topK?: number;
      enableCache?: boolean;
    } = {}
  ): Promise<{
    results: any[];
    metadata: {
      query: string;
      detectedMode: string;
      actualMode: string;
      executionTime: number;
      embeddingGenerated: boolean;
      cacheHit: boolean;
    };
  }> {
    const {
      tableName = 'documents', // Valeur par défaut pour les tests
      mode = 'auto',
      topK = 10,
      enableCache = true
    } = options;

    const startTime = Date.now();

    try {
      // ÉTAPE 1: Détecter le mode optimal
      const detectedMode = this.detectSearchMode(query, mode);
      Logger.debug(`🎯 Mode détecté: ${detectedMode} pour: "${query.substring(0, 50)}..."`);

      // ÉTAPE 2: Exécuter la recherche selon le mode
      let results: any[] = [];
      let metadata: any = {
        query,
        detectedMode,
        actualMode: detectedMode,
        executionTime: 0,
        embeddingGenerated: false,
        cacheHit: false
      };

      switch (detectedMode) {
        case 'text': {
          const textResult = await this.hybridSearch.textSearch(query, tableName, 'content', topK);
          results = textResult.results;
          metadata = { ...metadata, ...textResult.metadata };
          break;
        }

        case 'vector': {
          const vectorResult = await this.performVectorSearch(query, tableName, topK, enableCache);
          results = vectorResult.results;
          metadata = {
            ...metadata,
            ...vectorResult.metadata,
            embeddingGenerated: true,
            cacheHit: vectorResult.fromCache
          };
          break;
        }

        case 'hybrid': {
          const hybridResult = await this.hybridSearch.search(query, {
            tableName,
            topK,
            hybridMode: true,
            useCache: enableCache
          });
          results = hybridResult.results;
          metadata = {
            ...metadata,
            ...hybridResult.metadata,
            embeddingGenerated: true
          };
          break;
        }

        default:
          throw new Error(`Mode non supporté: ${detectedMode}`);
      }

      metadata.executionTime = Date.now() - startTime;

      Logger.info(`✅ Recherche ${detectedMode} terminée: ${results.length} résultats en ${metadata.executionTime}ms`);

      return {
        results,
        metadata
      };

    } catch (error: any) {
      Logger.error('❌ Erreur recherche intelligente:', error.message);
      throw new Error(`Échec de recherche: ${error.message}`);
    }
  }

  /**
   * Détecte le mode optimal pour une requête
   */
  private detectSearchMode(userQuery: string, requestedMode: string): string {
    const query = userQuery.toLowerCase().trim();

    // Mode explicite demandé
    if (requestedMode !== 'auto') {
      return requestedMode;
    }

    // Mots-clés de test/debug - rediriger vers pgvector_search avec useRandomVector
    if (
      query.startsWith('test:') ||
      query.startsWith('debug:') ||
      query.startsWith('random:') ||
      query.includes('performance') ||
      query.includes('benchmark')
    ) {
      Logger.info('💡 Utilisez pgvector_search avec useRandomVector: true pour les tests');
      return 'text'; // Mode par défaut pour les tests dans intelligent_search
    }

    // Requête très courte - full-text suffisant
    if (query.split(' ').length <= 2) {
      return 'text';
    }

    // Requête complexe - hybride recommandé
    if (
      query.includes('comment') ||
      query.includes('pourquoi') ||
      query.includes('quelle est') ||
      query.length > 50
    ) {
      return 'hybrid';
    }

    // Par défaut: vecteur
    return 'vector';
  }

  /**
   * Recherche avec vecteur aléatoire
   */
  private async performRandomSearch(
    tableName: string,
    topK: number
  ): Promise<any[]> {
    const client = await this.pool.connect();

    try {
      // Générer un vecteur aléatoire 768D
      const randomVector = [];
      for (let i = 0; i < 768; i++) {
        randomVector.push((Math.random() * 2) - 1);
      }

      // Normaliser
      const magnitude = Math.sqrt(randomVector.reduce((sum, val) => sum + val * val, 0));
      const normalizedVector = randomVector.map(val => val / magnitude);

      // Recherche
      const results = await client.query(
        `
        SELECT *, 1 - (embedding <=> $1::vector) as similarity
        FROM ${tableName}
        ORDER BY embedding <=> $1::vector
        LIMIT $2
        `,
        [`[${normalizedVector.join(',')}]`, topK]
      );

      Logger.info('🎲 Recherche aléatoire effectuée');
      return results.rows;

    } finally {
      client.release();
    }
  }

  /**
   * Recherche vecteur seule
   */
  private async performVectorSearch(
    query: string,
    tableName: string,
    topK: number,
    useCache: boolean
  ): Promise<{ results: any[]; metadata: any; fromCache: boolean }> {
    const client = await this.pool.connect();

    try {
      // Générer l'embedding
      const embedding = await embeddingService.generateEmbedding(query, { useCache });

      // Vérifier si vient du cache
      const fromCache = false; // Note: Cette vérification pourrait être améliorée avec un cache LRU

      // Recherche
      const results = await client.query(
        `
        SELECT *, 1 - (embedding <=> $1::vector) as similarity
        FROM ${tableName}
        ORDER BY embedding <=> $1::vector
        LIMIT $2
        `,
        [`[${embedding.join(',')}]`, topK]
      );

      return {
        results: results.rows,
        metadata: {
          embeddingDimensions: embedding.length,
          queryLength: query.length
        },
        fromCache
      };

    } finally {
      client.release();
    }
  }

  /**
   * Analyse et suggère des optimisations
   */
  async analyzeQuery(query: string): Promise<{
    mode: string;
    confidence: number;
    reasoning: string[];
    suggestions: string[];
  }> {
    const mode = this.detectSearchMode(query, 'auto');
    const reasoning: string[] = [];
    const suggestions: string[] = [];

    // Analyser la requête
    const words = query.split(' ').length;
    const length = query.length;

    if (words <= 2) {
      reasoning.push('Requête courte - full-text suffira');
      suggestions.push('Utilisez le mode "text" pour plus de rapidité');
    }

    if (query.includes('comment') || query.includes('pourquoi')) {
      reasoning.push('Question complexe - vecteur recommandé');
      suggestions.push('Mode "hybrid" offrira les meilleurs résultats');
    }

    if (query.startsWith('test:') || query.startsWith('debug:')) {
      reasoning.push('Requête de test détectée');
      suggestions.push('Utilisez pgvector_search avec useRandomVector: true pour les tests');
    }

    if (length > 100) {
      reasoning.push('Requête longue - vecteur plus précis');
      suggestions.push('Mode "hybrid" pour combiner vitesse et précision');
    }

    // Calculer la confiance
    let confidence = 0.5;
    if (mode === 'text' && words <= 2) confidence = 0.8;
    if (mode === 'hybrid' && (query.includes('comment') || length > 50)) confidence = 0.9;
    if (mode === 'vector' && length > 20 && words > 2) confidence = 0.7;

    return {
      mode,
      confidence,
      reasoning,
      suggestions
    };
  }

  /**
   * Benchmark des différents modes
   */
  async benchmark(
    testQueries: string[],
    tableName: string,
    iterations: number = 3
  ): Promise<{
    text: { avgTime: number; successRate: number };
    vector: { avgTime: number; successRate: number };
    hybrid: { avgTime: number; successRate: number };
  }> {
    Logger.info(`🧪 Benchmark sur ${testQueries.length} requêtes (${iterations} itérations)...`);

    const modes = ['text', 'vector', 'hybrid'];
    const results: any = {};

    for (const mode of modes) {
      let totalTime = 0;
      let successCount = 0;

      for (let i = 0; i < iterations; i++) {
        for (const query of testQueries) {
          try {
            const start = Date.now();
            await this.search(query, { tableName, mode: mode as any });
            totalTime += Date.now() - start;
            successCount++;
          } catch (_error) {
            Logger.error(`❌ Échec mode ${mode}: "${query}"`);
          }
        }
      }

      results[mode] = {
        avgTime: totalTime / (testQueries.length * iterations),
        successRate: (successCount / (testQueries.length * iterations)) * 100
      };

      Logger.info(`✅ ${mode}: ${results[mode].avgTime.toFixed(2)}ms avg, ${results[mode].successRate.toFixed(1)}% success`);
    }

    return results;
  }

  /**
   * Suggestions de requêtes (délégué à HybridSearchService)
   */
  async getSuggestions(
    partialQuery: string,
    tableName: string,
    contentColumn: string = 'content',
    limit: number = 5
  ): Promise<string[]> {
    return this.hybridSearch.getSuggestions(partialQuery, tableName, contentColumn, limit);
  }
}

import { Pool } from 'pg';

// Types pour les analyses d'optimisation
export interface SlowQuery {
  query: string;
  duration: number;
  calls: number;
  mean_time: number;
  total_time: number;
}

export interface IndexInfo {
  tablename: string;
  indexname: string;
  indexdef: string;
  size: string;
  usage: number;
}

export interface TableStats {
  tablename: string;
  seq_scan: number;
  seq_tup_read: number;
  idx_scan: number;
  idx_tup_fetch: number;
  n_tup_ins: number;
  n_tup_upd: number;
  n_tup_del: number;
  n_live_tup: number;
  n_dead_tup: number;
  last_vacuum?: string;
  last_autovacuum?: string;
  last_analyze?: string;
  last_autoanalyze?: string;
}

export interface MissingIndex {
  table: string;
  columns: string;
  suggested_index: string;
  potential_impact: 'HIGH' | 'MEDIUM' | 'LOW';
  estimated_gain: string;
}

// Classe pour l'optimisation de base de donnÃ©es
export class DBOptimizer {
  constructor(private pool: Pool) {}

  // Obtenir les requÃªtes lentes depuis pg_stat_statements
  async getSlowQueries(limit: number = 10): Promise<SlowQuery[]> {
    const query = `
      SELECT
        query,
        calls,
        total_exec_time as total_time,
        mean_exec_time as mean_time,
        total_exec_time / calls as avg_time
      FROM pg_stat_statements
      ORDER BY mean_exec_time DESC
      LIMIT $1
    `;

    try {
      const result = await this.pool.query(query, [limit]);
      return result.rows.map(row => ({
        query: row.query,
        duration: parseFloat(row.mean_time),
        calls: parseInt(row.calls),
        mean_time: parseFloat(row.mean_time),
        total_time: parseFloat(row.total_time)
      }));
    } catch (error: any) {
      throw new Error(`Erreur lors de la rÃ©cupÃ©ration des requÃªtes lentes: ${error.message}`);
    }
  }

  // Analyser l'utilisation des index
  async analyzeIndexUsage(): Promise<IndexInfo[]> {
    const query = `
      SELECT
        i.schemaname,
        i.tablename,
        i.indexname,
        i.indexdef,
        pg_size_pretty(pg_relation_size(s.indexrelid)) as size,
        s.idx_scan as usage
      FROM pg_indexes i
      JOIN pg_stat_user_indexes s ON i.tablename = s.relname AND i.indexname = s.indexrelname AND i.schemaname = s.schemaname
      WHERE i.schemaname = 'public'
      ORDER BY s.idx_scan ASC, pg_relation_size(s.indexrelid) DESC
    `;

    try {
      const result = await this.pool.query(query);
      return result.rows.map(row => ({
        tablename: row.tablename,
        indexname: row.indexname,
        indexdef: row.indexdef,
        size: row.size,
        usage: parseInt(row.usage || 0)
      }));
    } catch (error: any) {
      throw new Error(`Erreur lors de l'analyse des index: ${error.message}`);
    }
  }

  // Obtenir les statistiques des tables
  async getTableStatistics(): Promise<TableStats[]> {
    const query = `
      SELECT
        schemaname,
        relname as tablename,
        seq_scan,
        seq_tup_read,
        idx_scan,
        idx_tup_fetch,
        n_tup_ins,
        n_tup_upd,
        n_tup_del,
        n_live_tup,
        n_dead_tup,
        last_vacuum,
        last_autovacuum,
        last_analyze,
        last_autoanalyze,
        vacuum_count,
        autovacuum_count,
        analyze_count,
        autoanalyze_count
      FROM pg_stat_user_tables
      WHERE schemaname = 'public'
      ORDER BY (n_dead_tup::float / GREATEST(n_live_tup + n_dead_tup, 1)) DESC
    `;

    try {
      const result = await this.pool.query(query);
      return result.rows.map(row => ({
        tablename: row.tablename,
        seq_scan: parseInt(row.seq_scan || 0),
        seq_tup_read: parseInt(row.seq_tup_read || 0),
        idx_scan: parseInt(row.idx_scan || 0),
        idx_tup_fetch: parseInt(row.idx_tup_fetch || 0),
        n_tup_ins: parseInt(row.n_tup_ins || 0),
        n_tup_upd: parseInt(row.n_tup_upd || 0),
        n_tup_del: parseInt(row.n_tup_del || 0),
        n_live_tup: parseInt(row.n_live_tup || 0),
        n_dead_tup: parseInt(row.n_dead_tup || 0),
        last_vacuum: row.last_vacuum,
        last_autovacuum: row.last_autovacuum,
        last_analyze: row.last_analyze,
        last_autoanalyze: row.last_autoanalyze
      }));
    } catch (error: any) {
      throw new Error(`Erreur lors de la rÃ©cupÃ©ration des statistiques: ${error.message}`);
    }
  }

  // SuggÃ©rer des index manquants basÃ©s sur les requÃªtes lentes
  async suggestMissingIndexes(): Promise<MissingIndex[]> {
    const suggestions: MissingIndex[] = [];

    // Analyser les requÃªtes avec beaucoup de seq_scan
    const tablesWithHighSeqScan = await this.pool.query(`
      SELECT
        relname as tablename,
        seq_scan,
        seq_tup_read
      FROM pg_stat_user_tables
      WHERE seq_scan > 1000
        AND seq_tup_read > 10000
      ORDER BY seq_scan DESC
    `);

    for (const table of tablesWithHighSeqScan.rows) {
      // SuggÃ©rer des index basÃ©s sur les colonnes frÃ©quemment utilisÃ©es dans WHERE
      const commonWhereColumns = await this.pool.query(`
        SELECT
          attname as column_name
        FROM pg_attribute a
        JOIN pg_class c ON a.attrelid = c.oid
        JOIN pg_namespace n ON c.relnamespace = n.oid
        WHERE c.relname = $1
          AND n.nspname = 'public'
          AND a.attnum > 0
          AND NOT a.attisdropped
          AND a.attnotnull = true
        ORDER BY a.attnum
      `, [table.tablename]);

      if (commonWhereColumns.rows.length > 0) {
        const columns = commonWhereColumns.rows
          .slice(0, 3) // Prendre les 3 premiÃ¨res colonnes
          .map(col => col.column_name)
          .join(', ');

        suggestions.push({
          table: table.tablename,
          columns,
          suggested_index: `CREATE INDEX idx_${table.tablename}_${commonWhereColumns.rows[0].column_name} ON ${table.tablename} (${columns});`,
          potential_impact: table.seq_scan > 10000 ? 'HIGH' : 'MEDIUM',
          estimated_gain: `RÃ©duction potentielle de ${Math.round((table.seq_scan / (table.seq_scan + 100)) * 100)}% des sequential scans`
        });
      }
    }

    return suggestions;
  }

  // Analyser les tables qui nÃ©cessitent un VACUUM
  async getTablesNeedingVacuum(): Promise<any[]> {
    const query = `
      SELECT
        schemaname,
        relname as tablename,
        n_live_tup,
        n_dead_tup,
        (n_dead_tup::float / GREATEST(n_live_tup + n_dead_tup, 1)) * 100 as dead_tuple_percent,
        last_vacuum,
        last_autovacuum,
        last_analyze,
        last_autoanalyze,
        pg_size_pretty(pg_total_relation_size(schemaname||'.'||relname)) as table_size
      FROM pg_stat_user_tables
      WHERE schemaname = 'public'
        AND n_dead_tup > 1000
        AND (n_dead_tup::float / GREATEST(n_live_tup + n_dead_tup, 1)) > 0.1
      ORDER BY dead_tuple_percent DESC
    `;

    try {
      const result = await this.pool.query(query);
      // Formatter dead_tuple_percent en JavaScript (plus compatible)
      return result.rows.map(row => ({
        ...row,
        dead_tuple_percent: parseFloat(row.dead_tuple_percent || 0).toFixed(2)
      }));
    } catch (error: any) {
      throw new Error(`Erreur lors de l'analyse VACUUM: ${error.message}`);
    }
  }

  // Obtenir les informations de cache
  async getCacheHitRatios(): Promise<any> {
    const query = `
      SELECT
        sum(heap_blks_read) as heap_read,
        sum(heap_blks_hit) as heap_hit,
        sum(heap_blks_hit) / nullif(sum(heap_blks_hit) + sum(heap_blks_read), 0) as heap_ratio,
        sum(idx_blks_read) as idx_read,
        sum(idx_blks_hit) as idx_hit,
        sum(idx_blks_hit) / nullif(sum(idx_blks_hit) + sum(idx_blks_read), 0) as idx_ratio
      FROM pg_statio_user_tables;
    `;

    try {
      const result = await this.pool.query(query);
      return result.rows[0];
    } catch (error: any) {
      throw new Error(`Erreur lors de l'analyse du cache: ${error.message}`);
    }
  }

  // Analyser les locks actifs
  async getActiveLocks(): Promise<any[]> {
    const query = `
      SELECT
        t.relname as table_name,
        l.mode,
        l.granted,
        a.usename as username,
        a.query,
        a.query_start,
        now() - a.query_start as duration
      FROM pg_locks l
      JOIN pg_class t ON l.relation = t.oid
      JOIN pg_stat_activity a ON l.pid = a.pid
      WHERE t.relname IS NOT NULL
        AND l.mode NOT IN ('AccessShareLock')
      ORDER BY a.query_start;
    `;

    try {
      const result = await this.pool.query(query);
      return result.rows;
    } catch (error: any) {
      throw new Error(`Erreur lors de l'analyse des locks: ${error.message}`);
    }
  }

  // Analyser les requÃªtes en cours d'exÃ©cution
  async getRunningQueries(): Promise<any[]> {
    const query = `
      SELECT
        pid,
        usename as username,
        application_name,
        client_addr,
        state,
        query,
        query_start,
        now() - query_start as duration,
        wait_event_type,
        wait_event
      FROM pg_stat_activity
      WHERE state != 'idle'
        AND query NOT LIKE '%pg_stat_activity%'
      ORDER BY query_start;
    `;

    try {
